from fractions import Fraction


def next_state(pattern, k, flip):
    """Holding the first k letters of pattern, flip one more: return the new number held."""
    s = pattern[:k] + flip
    while s and not pattern.startswith(s):
        s = s[1:]
    return len(s)


def solve(A, b):
    """Solve A x = b exactly (lists of Fractions) by Gauss-Jordan elimination."""
    n = len(b)
    A = [row[:] + [b[i]] for i, row in enumerate(A)]
    for i in range(n):
        piv = next(r for r in range(i, n) if A[r][i] != 0)
        A[i], A[piv] = A[piv], A[i]
        for r in range(n):
            if r != i and A[r][i] != 0:
                f = A[r][i] / A[i][i]
                A[r] = [x - f * y for x, y in zip(A[r], A[i])]
    return [A[i][n] / A[i][i] for i in range(n)]

widget.solution:
from fractions import Fraction


def wait_time(pattern, p=Fraction(1, 2)):
    p = Fraction(p)
    n = len(pattern)
    A = [[Fraction(0)] * n for _ in range(n)]
    b = [Fraction(1)] * n
    for k in range(n):
        A[k][k] += 1
        for flip, chance in (('H', p), ('T', 1 - p)):
            j = next_state(pattern, k, flip)
            if j < n:
                A[k][j] -= chance
    return solve(A, b)[0]
